import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
import { performance } from 'node:perf_hooks';
const temporary = path.dirname(import.meta.filename);
const root = '/home/ubuntu/github/keelson';
const esbuild = await import(pathToFileURL(path.join(temporary, 'node_modules/esbuild/lib/main.js')));
await esbuild.build({ entryPoints: [path.join(root, 'src/commands/status.js')], bundle: true, platform: 'node', format: 'esm', banner: {js: 'import { createRequire as bundleCreateRequire } from "node:module"; const require = bundleCreateRequire(import.meta.url);'}, outfile: path.join(temporary, 'status.mjs'), plugins: [{name:'preserve-original-url-for-diagnostic', setup(build) { build.onLoad({filter:/\.js$/}, async (args) => ({contents: fs.readFileSync(args.path,'utf8').replaceAll('import.meta.url', JSON.stringify(pathToFileURL(args.path).href)),loader:'js'}));}}] });
const output = {diagnosticOnly:true, esbuild:esbuild.version, samples:10, cases:{}};
for(const [name,module] of [['original',path.join(root,'src/commands/status.js')],['bundled',path.join(temporary,'status.mjs')]]) {
 const samples=[];
 for(let i=0;i<10;i++) { const start=performance.now(); const result=spawnSync(process.execPath,['--input-type=module','-e',`await import(${JSON.stringify(pathToFileURL(module).href)})`],{encoding:'utf8',cwd:root}); if(result.status!==0)throw new Error(result.stderr);samples.push(+(performance.now()-start).toFixed(3)); }
 output.cases[name]=samples;
}
fs.writeFileSync(path.join(temporary,'diagnostic.json'),JSON.stringify(output,null,2)+'\n');
console.log(JSON.stringify(output));
